import {parseMarkdown,matches,schedule,pickCards,attachIds} from './core.js';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sample=`# 学び方の基本
## 答えを見ずに思い出す練習を英語で？
答え: retrieval practice | リトリーバルプラクティス
解説: 思い出そうとする行為そのものが、記憶の定着を助けます。

## 間隔を空けて繰り返し学ぶ方法は？
答え: 間隔反復 | spaced repetition
解説: まとめて繰り返すより、日を分けて復習することを意識しましょう。

## カード1枚で問う内容は、原則いくつ？
答え: 1つ | 一つ | 1
解説: 短い問いに分けると、何を覚えていないかが明確になります。

## 回答後に正解を確認することを英語で？
答え: feedback | フィードバック
解説: 間違いをそのままにせず、正解と理由を確認しましょう。

## 暗記の進歩は、入力速度と何を分けて測る？
答え: 正答率 | 想起の正確さ
解説: 速く打てることと、覚えていることは別に評価します。`;
const english=`# 日常の英単語
## 「思い出す」を英語で？
答え: recall | remember
解説: I can recall that moment.
## 「習慣」を英語で？
答え: habit
解説: A small habit makes a big difference.
## 「好奇心」を英語で？
答え: curiosity
解説: Stay curious. 好奇心を持ち続けよう。
## 「進歩」を英語で？
答え: progress
解説: Make progress every day.
## 「自信」を英語で？
答え: confidence
解説: Build confidence through practice.`;
const web=`# Webの基礎知識
## Webページの構造を記述する言語は？
答え: HTML
解説: HyperText Markup Languageの略です。
## Webページの見た目を指定する言語は？
答え: CSS
解説: Cascading Style Sheetsの略です。
## Webブラウザで動く代表的なプログラミング言語は？
答え: JavaScript | JS
解説: ページの動作や操作への反応を実装します。
## HTTPで「見つからない」を表すステータスコードは？
答え: 404
解説: リクエスト先のリソースが見つからないことを表します。
## Gitで変更履歴を記録する操作は？
答え: commit | コミット
解説: 変更内容をまとまりごとに記録します。`;
const defaults=[{id:'learn',markdown:sample,icon:'🌱',description:'まずは5問。覚え方を、覚える。'},{id:'english',markdown:english,icon:'🍊',description:'日常で使えることばを、少しずつ。'},{id:'web',markdown:web,icon:'⌘',description:'仕組みを理解して、知識をつなぐ。'}];
let state={decks:defaults,progress:{},sessions:[]},storageOK=true;
try{const stored=JSON.parse(localStorage.getItem('oboe-sushi-v1')||'null');if(stored&&Array.isArray(stored.decks)&&stored.decks.every(d=>typeof d.markdown==='string'&&typeof d.id==='string')&&stored.progress&&Array.isArray(stored.sessions))state=stored;}catch{storageOK=false;}
const decks=()=>state.decks.map(d=>({...d,...parseMarkdown(d.markdown),cards:attachIds(parseMarkdown(d.markdown).cards,d.id)}));
const persist=()=>{try{localStorage.setItem('oboe-sushi-v1',JSON.stringify(state));return true;}catch{storageOK=false;toast('保存できません。ブラウザのストレージ設定を確認してください。');return false;}};
let view='home',selected=state.decks[0]?.id,session=null,timer=null,editing=null,composing=false,deadline=0;
const main=$('#main');
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500);}
function dueCount(d){return d.cards.filter(c=>(state.progress[c.id]?.due||0)<=Date.now()).length;}
function navigate(next){clearInterval(timer);session=null;view=next;render();window.scrollTo(0,0);}
function render(){document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===view));if(view==='home')home();else if(view==='library')library();else if(view==='research')research();}
const art=`<svg viewBox="0 0 460 270" role="img" aria-label="お皿に乗ったサーモン寿司のイラスト"><ellipse cx="240" cy="226" rx="157" ry="22" fill="#d9dacb"/><path d="M66 171 Q220 222 396 164 L396 185 Q234 259 66 193Z" fill="#355b4b"/><ellipse cx="231" cy="171" rx="165" ry="53" fill="#6e8872"/><ellipse cx="231" cy="168" rx="147" ry="42" fill="#e7e7cc"/><ellipse cx="231" cy="166" rx="126" ry="32" fill="#ced7b9"/><g transform="rotate(-12 220 130)"><path d="M143 118 Q143 93 175 93 L283 93 Q316 94 315 120 L308 157 Q235 184 148 154Z" fill="#fffdf2"/><path d="M151 128q9-8 13 2m10 13q8-9 13 0m19 12q7-8 13 0m18-14q8-10 13-1m18 11q8-9 13-1m16-22q8-9 12-1" fill="none" stroke="#e1dfcc" stroke-width="3"/><path d="M126 106 Q140 75 178 72 L281 72 Q314 72 334 102 L323 123 Q219 146 130 121Z" fill="#e7794e"/><path d="M153 79l37 49m2-55 38 58m3-59 39 55m4-53 37 44" stroke="#f9bd88" stroke-width="10" fill="none"/><path d="M129 106Q216 129 333 102" fill="none" stroke="#f29a6b" stroke-width="5"/></g><path d="M345 147q-15-15-7-24 15-4 22 15 5-19 18-14 6 13-11 23" fill="#87995a"/><path d="M99 105l-8-12m13 4 2-14m265-5 6-13m2 22 13-3" stroke="#c6a762" stroke-width="3" stroke-linecap="round"/><circle cx="118" cy="57" r="3" fill="#c6a762"/><circle cx="340" cy="53" r="4" fill="#c6a762"/></svg>`;
function home(){const ds=decks(),total=ds.reduce((n,d)=>n+dueCount(d),0),todayKey=new Date().toLocaleDateString('sv-SE'),today=state.sessions.filter(s=>new Date(s.at).toLocaleDateString('sv-SE')===todayKey).reduce((n,s)=>n+s.count,0);main.innerHTML=`<section class="hero"><div class="hero-copy"><span class="eyebrow">A LITTLE PRACTICE, A LASTING MEMORY.</span><h1>思い出して、打って、<br><em>知識をひと皿ずつ。</em></h1><p>眺めるだけの暗記から、思い出す練習へ。<br>あなたのノートが、毎日続くタイピング学習に。</p></div><div class="hero-art">${art}<span class="art-note">おいしく、たのしく、記憶に残す。</span></div></section><section class="today" aria-label="今日の学習"><div><div class="today-label">今日の復習</div><strong>${total}<small>枚</small></strong></div><div class="stat"><div class="today-label">今日取り組んだカード</div><strong>${today}<small>枚</small></strong></div><div class="stat"><div class="today-label">まずは小さく</div><strong>5<small>問から</small></strong></div><button class="primary" id="quick-start" ${!ds.length?'disabled':''}>ひと皿、学ぶ <span aria-hidden="true">→</span></button></section><section><div class="section-head"><div><h2>今日のデッキ</h2><p>気になるテーマを選んで、さっそく始めよう。</p></div><button class="text-button" id="add-deck">＋ デッキをつくる</button></div><div class="decks">${ds.map(d=>`<article class="deck ${selected===d.id?'selected':''}"><div class="deck-top"><span class="deck-icon">${esc(d.icon||'📚')}</span><span class="pill">${dueCount(d)}枚 復習待ち</span></div><h3>${esc(d.title)}</h3><p>${esc(d.description||'あなたのノートからつくったデッキ。')}</p><div class="deck-bottom"><span>${d.cards.length} cards</span><button data-start="${esc(d.id)}">このデッキで学ぶ →</button></div></article>`).join('')}</div></section><div class="bottom-grid"><aside class="tip"><span>✧</span><div><h3>「思い出せない」も、学びのはじまり。</h3><p>答えを見ずに、まずはひと呼吸。間違えたら正解を確認して、<br>次の復習でまた会いましょう。</p><button class="text-button" data-hints>学び方のヒントを読む ↗</button></div></aside><section class="activity"><h3>少しずつ、積み重ねる <span class="tiny">直近7日</span></h3><div class="days">${Array.from({length:7},(_,i)=>{const date=new Date();date.setDate(date.getDate()-6+i);const yes=state.sessions.some(s=>new Date(s.at).toLocaleDateString('sv-SE')===date.toLocaleDateString('sv-SE'));return `<div class="day ${yes?'done':''}"><b>${yes?'✓':'·'}</b>${['日','月','火','水','木','金','土'][date.getDay()]}</div>`;}).join('')}</div></section></div><p class="source-note">おぼえ寿司は、想起練習と間隔反復を取り入れた試作アプリです。Anki・寿司打との公式な提携はありません。<br>カードと学習記録はこのブラウザに保存されます。端末間同期はありません。${storageOK?'':' 保存機能を利用できない可能性があります。'}</p>`;
$('#quick-start').onclick=()=>setup(ds.find(d=>dueCount(d)>0)?.id||ds[0]?.id);$('#add-deck').onclick=()=>openEditor();main.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>setup(b.dataset.start));$('[data-hints]').onclick=()=>navigate('research');}
function setup(id){selected=id;const d=decks().find(d=>d.id===id);if(!d)return;navigate('home');main.innerHTML=`<div class="page-title"><span class="eyebrow">LET’S MAKE IT STICK</span><h1>${esc(d.title)}</h1><p>答えを思い出して入力。正解を確認したら、次のひと皿へ。</p></div><section class="game"><div class="conveyor"><div class="sushi-moving">🍣</div></div><h2>今日は、5問から始めよう。</h2><p>初めての問題は、答えを見て学んでも大丈夫。<br>不正解のカードは10分後、正解のカードは翌日以降に復習します。</p><div class="settings" style="justify-content:center"><label>出題数 <select id="count"><option value="5">5問</option><option value="10">10問</option><option value="20">20問</option></select></label><label>モード <select id="mode"><option value="relax">じっくり・時間制限なし</option><option value="timed">チャレンジ・1問30秒</option></select></label></div><button class="primary" id="begin">学習をはじめる →</button><p class="tiny">${dueCount(d)>0?'復習期限の来たカードを優先します。':'今日の復習は完了！追加練習として出題します。'} 答えは日本語・英語どちらも入力できます。</p><button class="text-button" id="back">ホームに戻る</button></section>`;$('#back').onclick=()=>navigate('home');$('#begin').onclick=()=>{const count=Number($('#count').value),mode=$('#mode').value;const due=d.cards.filter(c=>(state.progress[c.id]?.due||0)<=Date.now());start(d,pickCards(due.length?due:d.cards,state.progress,count),mode);};}
function start(deck,cards,mode){if(!cards.length)return toast('カードを登録してください。');session={deck,cards,mode,index:0,results:[],started:performance.now(),typingMs:0};showQuestion();}
function showQuestion(){clearInterval(timer);const s=session,c=s.cards[s.index];composing=false;s.answered=false;s.questionAt=performance.now();main.innerHTML=`<div class="game-head"><button class="text-button" id="exit">← 学習を終了</button><h2>${esc(s.deck.title)}</h2><span>${s.index+1} / ${s.cards.length}</span></div><div class="progress-track"><div class="progress-fill" style="width:${s.index/s.cards.length*100}%"></div></div><section class="game"><span class="eyebrow">RECALL FIRST. TYPE SECOND.</span><div class="conveyor"><div class="sushi-moving">${['🍣','🍤','🍙'][s.index%3]}</div></div><span class="pill" id="clock">${s.mode==='timed'?'残り 30 秒':'じっくりモード'}</span><div class="question">${esc(c.question)}</div><form class="answer-form" id="answer-form"><input id="answer" aria-label="答え" placeholder="思い出した答えを入力…" autocomplete="off" autocapitalize="off" spellcheck="false" maxlength="1000"><button class="primary" type="submit">答え合わせ</button></form><p class="game-help">Enterで答え合わせ · 日本語は変換を確定してから送信</p><button class="text-button" id="reveal">まだ覚えていない・答えを見る</button><div id="feedback" aria-live="polite"></div></section>`;const input=$('#answer');input.addEventListener('compositionstart',()=>composing=true);input.addEventListener('compositionend',()=>composing=false);input.onkeydown=e=>{if(e.key==='Enter'&&(e.isComposing||e.keyCode===229))e.preventDefault();};$('#answer-form').onsubmit=e=>{e.preventDefault();if(composing||!input.value.trim())return;answer(false);};$('#reveal').onclick=()=>answer(true);$('#exit').onclick=()=>{if(confirm('ここまでの回答は保存済みです。学習を終了しますか？'))navigate('home');};input.focus();if(s.mode==='timed'){deadline=performance.now()+30000;timer=setInterval(()=>{if(document.hidden)return;if(composing){deadline+=250;return;}const remaining=Math.max(0,Math.ceil((deadline-performance.now())/1000));$('#clock').textContent=`残り ${remaining} 秒`;if(remaining===0)answer(true);},250);}}
function answer(revealed){if(!session||session.answered)return;const s=session,c=s.cards[s.index],value=$('#answer').value,correct=!revealed&&matches(value,c.answers);s.answered=true;clearInterval(timer);const duration=performance.now()-s.questionAt;s.typingMs+=duration;s.results.push({card:c,correct,value,duration});if(!s.retry)state.progress[c.id]=schedule(state.progress[c.id],correct);persist();$('#answer').disabled=true;$('#answer-form button').disabled=true;$('#reveal').hidden=true;$('#feedback').innerHTML=`<div class="feedback ${correct?'':'wrong'}"><strong>${correct?'✓ 正解。ひとつ、積み重なりました。':revealed?'答えを確認して、次につなげよう。':'あと少し。正解を確認しよう。'}</strong><div class="correct-answer">${esc(c.answers[0])}</div>${c.answers.length>1?`<p>別解：${esc(c.answers.slice(1).join(' / '))}</p>`:''}${!revealed&&!correct?`<p>あなたの回答：${esc(value)}</p>`:''}<p>${esc(c.explanation)}</p><p class="tiny">次の復習：${correct?(s.retry?'予定どおり':state.progress[c.id].interval+'日後'):'10分後'}${!correct?' · もう一度、答えを隠して思い出しましょう。':''}</p>${!correct&&!revealed?'<button class="text-button" id="accept">表記の違いだった（正解として記録）</button>':''}<br><button class="primary" id="next">${s.index+1===s.cards.length?'結果を見る':'次のひと皿へ →'}</button></div>`;$('#next').onclick=()=>{s.index++;if(s.index>=s.cards.length)finish();else showQuestion();};$('#accept')?.addEventListener('click',()=>{if(!s.retry){const p=state.progress[c.id];p.attempts--;state.progress[c.id]=schedule({...p,interval:0},true);}s.results[s.results.length-1].correct=true;persist();$('#accept').disabled=true;$('#accept').textContent=s.retry?'正解として記録しました（復習予定を維持）':'正解として記録しました（次回：1日後）';});$('#next').focus();}
function finish(){clearInterval(timer);const s=session,correct=s.results.filter(r=>r.correct).length;state.sessions.push({at:Date.now(),deck:s.deck.id,count:s.results.length,correct});state.sessions=state.sessions.slice(-1000);persist();main.innerHTML=`<section class="result"><span class="eyebrow">ONE PLATE AT A TIME.</span><div style="font-size:65px;margin-top:20px">🍵</div><h1>今日のひと皿、ごちそうさま。</h1><p>思い出そうとした分だけ、次の一歩に。<br>また明日、少しずつ積み重ねましょう。</p><div class="result-stats"><div><strong>${correct} / ${s.results.length}</strong><span>正解したカード</span></div><div><strong>${Math.round(correct/s.results.length*100)}<small>%</small></strong><span>正答率</span></div><div><strong>${Math.round(s.typingMs/1000)}<small>秒</small></strong><span>回答に使った時間</span></div></div><p class="tiny">時間は入力・思考時間の合計です。正答率とは別の指標です。</p><div class="result-list">${s.results.map(r=>`<div class="result-row"><span>${r.correct?'✓':'↻'} ${esc(r.card.question)}</span><span class="tiny">${s.retry?'元の復習予定を維持':r.correct?'翌日以降に復習':'10分後に復習'}</span></div>`).join('')}</div><div class="result-actions"><button class="primary" id="retry" ${correct===s.results.length?'disabled':''}>間違えた問題をもう一度</button><button class="secondary" id="home">ホームに戻る</button></div><p class="tiny">すぐの再練習で正解しても、10分後の復習予定は維持します。</p></section>`;$('#home').onclick=()=>navigate('home');$('#retry').onclick=()=>{const wrong=s.results.filter(r=>!r.correct).map(r=>r.card);session=null;start(s.deck,wrong,'relax');session.retry=true;};session=null;}
function download(name,content,type='text/markdown'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function library(){main.innerHTML=`<div class="page-title"><span class="eyebrow">YOUR PERSONAL MENU</span><h1>カード管理</h1><p>ノートを、小さな問いに。自分だけのデッキを育てよう。</p><button class="primary" id="add">＋ Markdownから登録</button></div>${decks().map(d=>`<details class="library-card"><summary>${esc(d.icon||'📚')} ${esc(d.title)} <span class="tiny">${d.cards.length}枚・復習待ち${dueCount(d)}枚</span></summary>${d.cards.map(c=>`<div class="card-row"><b>${esc(c.question)}</b><span>${esc(c.answers.join(' / '))}</span><p>${esc(c.explanation)}</p></div>`).join('')}<div class="card-actions"><button class="text-button" data-edit="${esc(d.id)}">編集する</button><button class="text-button" data-export="${esc(d.id)}">Markdownを書き出す ↓</button><button class="text-button danger" data-delete="${esc(d.id)}">削除</button></div></details>`).join('')}<p class="tiny">編集したデッキの復習記録はリセットされます。Markdownの書き出しには復習記録は含まれません。</p>`;$('#add').onclick=()=>openEditor();main.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openEditor(b.dataset.edit));main.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>{const d=decks().find(d=>d.id===b.dataset.export);download(d.title+'.md',d.markdown);});main.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(!confirm('このデッキと復習記録を削除しますか？'))return;state.decks=state.decks.filter(d=>d.id!==b.dataset.delete);Object.keys(state.progress).filter(k=>k.startsWith(b.dataset.delete+':')).forEach(k=>delete state.progress[k]);persist();library();});}
function research(){main.innerHTML=`<section class="research"><div class="page-title"><span class="eyebrow">LEARN HOW TO LEARN</span><h1>速さよりも、思い出すこと。</h1><p>おぼえ寿司の学習設計と、上手なカードのつくり方。</p></div><article><h3>01　答えを見る前に、思い出す</h3><p>答えを表示して写すよりも、まず記憶から取り出す練習を。2025年の2実験では、頭の中だけで答える方法に比べ、実際に入力する方法で成績が高く、定義の問題で差が大きくなりました。タイピング自体があらゆる学習で優れると示すものではありません。</p><a href="https://link.springer.com/article/10.1007/s10648-025-10040-4" target="_blank" rel="noopener">Rivers, Northern & Tauber（2025）↗</a></article><article><h3>02　間違えたら、正解と理由を確かめる</h3><p>語彙学習の研究では、正解のフィードバックを伴う想起練習が再学習より良い結果を示しました。本アプリも毎回答えを表示します。初めての内容は、先に理解してからカードにしましょう。</p><a href="https://doi.org/10.1080/14790718.2022.2102172" target="_blank" rel="noopener">Retrieval practice plus feedback（2022オンライン公開）↗</a></article><article><h3>03　復習は、時間を空けて</h3><p>間隔学習のメタ分析では、保持したい期間と学習間隔の関係が示されています。本試作は不正解10分後・正解1日後から間隔を倍にする簡易方式です。これはアプリ上の仮設定であり、研究で検証された個人最適の間隔やAnkiのFSRS実装ではありません。</p><a href="https://pubmed.ncbi.nlm.nih.gov/16719566/" target="_blank" rel="noopener">Cepeda et al.（2006）↗</a></article><article><h3>04　カードは短く、問いは具体的に</h3><p>「HTTPについて説明」より「見つからないことを表すHTTPステータスコードは？」のように、答え合わせしやすい問いへ。答えは短く、解説に理由や例を書きます。同義語は <code>|</code> で区切って登録できます。</p><p>5問の目標・寿司の演出・時間制限の選択は、続けやすさを確かめるための設計仮説です。学習効果を保証するものではありません。Xを検索しましたが、根拠を確認できる該当投稿は得られず、上記の研究を設計の根拠にしています。</p><button class="text-button" id="create-hint">Markdownでカードをつくる →</button></article></section>`;$('#create-hint').onclick=()=>openEditor();}
function openEditor(id=null){editing=id;$('#markdown').value=id?state.decks.find(d=>d.id===id).markdown:`# マイデッキ\n\n## 水の化学式は？\n答え: H2O | H₂O\n解説: 水素原子2つと酸素原子1つからできています。\n\n## 「学ぶ」を英語で？\n答え: learn\n解説: Learn something new every day.\n`;preview();$('#editor').showModal();}
function preview(){const parsed=parseMarkdown($('#markdown').value);$('#save-deck').disabled=!!parsed.errors.length;$('#preview').innerHTML=parsed.errors.length?parsed.errors.map(e=>`<p class="error">${esc(e)}</p>`).join(''):`<b>${esc(parsed.title)} · ${parsed.cards.length}枚</b>`+parsed.cards.map(c=>`<p>${esc(c.question)} → ${esc(c.answers.join(' / '))}</p>`).join('');return parsed;}
$('#preview-button').onclick=preview;$('#markdown').oninput=preview;$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>500000)return toast('500KB以下のファイルを選んでください。');$('#markdown').value=await file.text();preview();e.target.value='';};$('#save-deck').onclick=()=>{const p=preview();if(p.errors.length)return;if(editing&&!confirm('編集すると、このデッキの復習記録がリセットされます。保存しますか？'))return;const id=editing||crypto.randomUUID();const d={id,markdown:$('#markdown').value,icon:'📚'};if(editing){state.decks=state.decks.map(x=>x.id===id?d:x);Object.keys(state.progress).filter(k=>k.startsWith(id+':')).forEach(k=>delete state.progress[k]);}else state.decks.push(d);persist();$('#editor').close();navigate('library');toast('デッキを登録しました。さっそく学んでみましょう。');};document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{if(session&&!confirm('学習を終了しますか？回答済みの記録は保存されています。'))return;navigate(b.dataset.view);});$('.brand').onclick=e=>{e.preventDefault();if(session&&!confirm('学習を終了しますか？'))return;navigate('home');};
document.addEventListener('visibilitychange',()=>{if(!session||session.answered||session.mode!=='timed')return;if(document.hidden){session.hiddenAt=performance.now();}else if(session.hiddenAt){deadline+=performance.now()-session.hiddenAt;session.hiddenAt=null;}});
render();
